// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller) public {
        // Restrict caller to be the owner to satisfy require condition
        vm.assume(caller == c.smartfix_owner());

        // Record the balance of the caller before the call
        uint256 callerBalanceBefore = address(caller).balance;

        // Drive the call as the caller
        vm.prank(caller);
        c.sudicideAnyone();

        // After selfdestruct, the caller should receive the contract's balance
        // In the reference, the contract's balance goes to msg.sender (the caller)
        // In the mutant, it goes to address(0) so the caller's balance doesn't increase
        uint256 callerBalanceAfter = address(caller).balance;

        // The contract balance before the call is the difference in caller's balance
        // Since msg.sender receives the contract's ether in the reference
        // General rule: caller's balance increases by the contract's balance at the time of selfdestruct
        // We can check that caller's balance increased (non-zero if contract had ether)
        assertTrue(callerBalanceAfter >= callerBalanceBefore);
    }
}

